        assert_eq!(board_id("/api/boards/b-1/ws"), Some("b-1"));
        assert_eq!(board_id("/api/boards//ws"), None);
        assert_eq!(board_id("/api/boards/a/b/ws"), None);
        assert_eq!(board_id("/"), None);
